```javascript
if (interaction.commandName === 'ban') {
  const user = interaction.options.getUser('user');
  const days = interaction.options.getNumber('days');
  const reason = interaction.options.getString('reason');

  // Perform the ban
  const member = await interaction.guild.members.fetch(user.id);
  if (!member.bannable) {
    return interaction.reply({
      content: 'I do not have permission to ban this user.',
      ephemeral: true,
    });
  }
  if (days) {
    await member.ban({ days: days, reason: reason });
  } else {
    await member.ban({ reason: reason });
  }

  // Send a confirmation message
  const message = `**${user.tag}** has been banned for ${days ? `${days} days` : ''} (${reason || 'No reason provided'})`;
  interaction.reply({ content: message, ephemeral: false });
}
```

